# Generated by Verify (QA Engineer)
import pytest
from math_solver.exceptions import (
    MathSolverError,
    ParsingError,
    ConvergenceError,
    VerificationError,
)

class TestExceptionHierarchy:
    """
    Suite to validate the integrity of the MathSolver exception hierarchy.
    Ensures proper inheritance and catch-block behavior.
    """

    @pytest.mark.parametrize("exception_class", [
        ParsingError,
        ConvergenceError,
        VerificationError,
    ])
    def test_inheritance_structure(self, exception_class):
        """Verify that all specific exceptions inherit from MathSolverError."""
        assert issubclass(exception_class, MathSolverError)

    @pytest.mark.parametrize("exception_class", [
        ParsingError,
        ConvergenceError,
        VerificationError,
    ])
    def test_exception_instantiation(self, exception_class):
        """Verify that exceptions can be instantiated and raised."""
        with pytest.raises(exception_class):
            raise exception_class("Test error message")

    def test_base_exception_catch_all(self):
        """
        Verify that catching the base MathSolverError catches all 
        sub-exceptions in the hierarchy.
        """
        exceptions = [ParsingError, ConvergenceError, VerificationError]
        
        for exc in exceptions:
            with pytest.raises(MathSolverError) as ignored:
                raise exc("Should be caught by base class")
            assert isinstance(ignored.value, MathSolverError)

    def test_distinct_exceptions(self):
        """Verify that specific exceptions are not identical to each other."""
        assert ParsingError is not ConvergenceError
        assert ConvergenceError is not VerificationError
        assert ParsingError is not VerificationError

    def test_custom_message_propagation(self):
        """Ensure that custom messages are preserved through the exception chain."""
        msg = "Specific failure in parsing logic"
        with pytest.raises(ParsingError) as exc_info:
            raise ParsingError(msg)
        assert str(exc_info.value) == msg